import re

_TOKEN_RE = re.compile(r"\s*(?:(<>|<=|>=|[+\-*/(),:=<>])|(\d+)|([A-Z][A-Z0-9]*))")
_FUNCS = {"SUM", "MIN", "MAX", "IF"}


def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    def parse_formula(src: str):
        tokens: list[tuple[str, str]] = []
        pos = 0
        n = len(src)
        while pos < n:
            m = _TOKEN_RE.match(src, pos)
            if not m:
                break
            pos = m.end()
            op, num, ident = m.groups()
            if op is not None:
                tokens.append(("OP", op))
            elif num is not None:
                tokens.append(("NUM", num))
            else:
                tokens.append(("ID", ident))
        tokens.append(("EOF", ""))
        idx = 0

        def parse_expr():
            nonlocal idx
            node = parse_term()
            while tokens[idx][0] == "OP" and tokens[idx][1] in ("+", "-"):
                op = tokens[idx][1]
                idx += 1
                right = parse_term()
                node = ("BIN", op, node, right)
            return node

        def parse_term():
            nonlocal idx
            node = parse_unary()
            while tokens[idx][0] == "OP" and tokens[idx][1] in ("*", "/"):
                op = tokens[idx][1]
                idx += 1
                right = parse_unary()
                node = ("BIN", op, node, right)
            return node

        def parse_unary():
            nonlocal idx
            if tokens[idx] == ("OP", "-"):
                idx += 1
                return ("NEG", parse_unary())
            return parse_atom()

        def parse_atom():
            nonlocal idx
            kind, val = tokens[idx]
            if kind == "NUM":
                idx += 1
                return ("NUM", int(val))
            if kind == "OP" and val == "(":
                idx += 1
                node = parse_expr()
                idx += 1  # ')'
                return node
            if kind == "ID":
                idx += 1
                if val in _FUNCS and tokens[idx] == ("OP", "("):
                    idx += 1  # '('
                    if val == "IF":
                        left = parse_expr()
                        cmp_op = tokens[idx][1]
                        idx += 1
                        right = parse_expr()
                        idx += 1  # ','
                        then_node = parse_expr()
                        idx += 1  # ','
                        else_node = parse_expr()
                        idx += 1  # ')'
                        return ("IF", cmp_op, left, right, then_node, else_node)
                    items = []
                    while True:
                        if (
                            tokens[idx][0] == "ID"
                            and tokens[idx + 1] == ("OP", ":")
                        ):
                            start = tokens[idx][1]
                            end = tokens[idx + 2][1]
                            idx += 3
                            c1, r1 = ord(start[0]), int(start[1:])
                            c2, r2 = ord(end[0]), int(end[1:])
                            c_lo, c_hi = (c1, c2) if c1 <= c2 else (c2, c1)
                            r_lo, r_hi = (r1, r2) if r1 <= r2 else (r2, r1)
                            for r in range(r_lo, r_hi + 1):
                                for c in range(c_lo, c_hi + 1):
                                    cname = f"{chr(c)}{r}"
                                    if cname in cells:
                                        items.append(("CELL", cname))
                        else:
                            items.append(parse_expr())
                        if tokens[idx] == ("OP", ","):
                            idx += 1
                        else:
                            break
                    idx += 1  # ')'
                    return ("AGG", val, items)
                return ("CELL", val)
            raise ValueError(f"Unexpected token: {tokens[idx]}")

        return parse_expr()

    def get_ast(name: str):
        raw = cells[name].strip()
        if raw.startswith("="):
            return parse_formula(raw[1:])
        return ("NUM", int(raw))

    results: dict[str, int | str] = {}
    in_progress: set[str] = set()

    def evaluate_cell(start_name: str) -> None:
        if start_name in results:
            return
        in_progress.add(start_name)
        stack: list[list] = [["CELL_EVAL", start_name]]
        node = get_ast(start_name)

        while True:
            # Descend until we produce a value `val`
            while True:
                kind = node[0]
                if kind == "NUM":
                    val: int | str = node[1]
                    break
                if kind == "CELL":
                    cname = node[1]
                    if cname in results:
                        val = results[cname]
                        break
                    if cname not in cells:
                        val = 0
                        break
                    if cname in in_progress:
                        val = "#CYCLE!"
                        break
                    in_progress.add(cname)
                    stack.append(["CELL_EVAL", cname])
                    node = get_ast(cname)
                elif kind == "NEG":
                    stack.append(["NEG"])
                    node = node[1]
                elif kind == "BIN":
                    stack.append(["BIN_L", node[1], node[3]])
                    node = node[2]
                elif kind == "AGG":
                    items = node[2]
                    if not items:
                        val = 0
                        break
                    stack.append(["AGG", node[1], items, 0, None])
                    node = items[0]
                elif kind == "IF":
                    stack.append(["IF_L", node[1], node[3], node[4], node[5]])
                    node = node[2]

            # Deliver `val` up the stack until a frame needs to evaluate a new node
            while stack:
                frame = stack.pop()
                fkind = frame[0]
                if fkind == "CELL_EVAL":
                    cname = frame[1]
                    in_progress.remove(cname)
                    results[cname] = val
                elif fkind == "NEG":
                    if not isinstance(val, str):
                        val = -val
                elif fkind == "BIN_L":
                    if not isinstance(val, str):
                        stack.append(["BIN_R", frame[1], val])
                        node = frame[2]
                        break
                elif fkind == "BIN_R":
                    if not isinstance(val, str):
                        op, lval = frame[1], frame[2]
                        if op == "+":
                            val = lval + val
                        elif op == "-":
                            val = lval - val
                        elif op == "*":
                            val = lval * val
                        else:  # "/"
                            if val == 0:
                                val = "#DIV/0!"
                            else:
                                q = abs(lval) // abs(val)
                                val = -q if (lval < 0) ^ (val < 0) else q
                elif fkind == "AGG":
                    if not isinstance(val, str):
                        fname, items, i, acc = frame[1], frame[2], frame[3], frame[4]
                        if acc is None:
                            acc = val
                        elif fname == "SUM":
                            acc += val
                        elif fname == "MIN":
                            if val < acc:
                                acc = val
                        else:  # MAX
                            if val > acc:
                                acc = val
                        i += 1
                        if i < len(items):
                            frame[3] = i
                            frame[4] = acc
                            stack.append(frame)
                            node = items[i]
                            break
                        val = acc
                elif fkind == "IF_L":
                    if not isinstance(val, str):
                        stack.append(["IF_R", frame[1], val, frame[3], frame[4]])
                        node = frame[2]
                        break
                elif fkind == "IF_R":
                    if not isinstance(val, str):
                        cmp_op, lval = frame[1], frame[2]
                        if cmp_op == "=":
                            cond = lval == val
                        elif cmp_op == "<>":
                            cond = lval != val
                        elif cmp_op == "<":
                            cond = lval < val
                        elif cmp_op == "<=":
                            cond = lval <= val
                        elif cmp_op == ">":
                            cond = lval > val
                        else:  # ">="
                            cond = lval >= val
                        node = frame[3] if cond else frame[4]
                        break
            else:
                return

    for cell_name in cells:
        evaluate_cell(cell_name)

    return results
